const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const query = $json.query ?? {};
const msg = body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || body.message || body;
const rawFrom = msg?.from || body.from || body.sender || body.phone || body?.message?.from || '';
const digits = String(rawFrom || '').replace(/\D/g, '');
const normalized = digits ? `+${digits}` : '';
const text = msg?.text?.body || body.text || body.message?.text || body.body?.text || body?.message?.body?.text || body?.message?.text?.body || '';
let messageId = msg?.id || body.message_id || body.message?.id || body.id || '';
if (!messageId) {
  messageId = `msg_${Date.now()}_${Math.floor(Math.random() * 100000)}`;
}

const timestamp = msg?.timestamp ? new Date(Number(msg.timestamp) * 1000).toISOString() : (body.timestamp || body.message?.timestamp || new Date().toISOString());
const media = msg?.image || msg?.document || msg?.video || null;
const messageType = media ? 'media' : 'text';
const mediaId = media?.id || body.media_id || '';
const mediaMime = media?.mime_type || body.media_mime || '';
const secretHeader = headers['x-origin-secret'] || headers['X-ORIGIN-SECRET'];
const secretQuery = query.secret || body.secret || '';
const providedSecret = secretHeader || secretQuery || '';
const secretValid = providedSecret !== '' && providedSecret === ($env.ORIGIN_SECRET || '');
return [{ json: { from_raw: rawFrom, from: normalized, text: String(text || ''), message_id: messageId, timestamp, message_type: messageType, media_id: mediaId, media_mime: mediaMime, secretValid } }];

const windowSec = 10;
const rows = $input.all().map(i => i.json).filter(r => String(r.status || '').toUpperCase() === 'PENDING');
const groups = {};
for (const row of rows) {
  const key = String(row.whatsapp || '').trim();
  if (!key) continue;
  if (!groups[key]) groups[key] = [];
  groups[key].push(row);
}
const now = new Date();
const result = [];
for (const [whatsapp, items] of Object.entries(groups)) {
  items.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
  const last = items[items.length - 1];
  const lastTs = new Date(last.timestamp);
  const diffSec = (now - lastTs) / 1000;
  if (diffSec < windowSec) continue;
  const combined = items.map(i => i.text).filter(Boolean).join('\n');
  const imageItems = items.filter(i => (i.media_id && String(i.media_mime || '').startsWith('image')));
  const batchId = `B${Date.now()}_${Math.floor(Math.random() * 1000)}`;
  result.push({ json: {
    whatsapp,
    combined_text: combined,
    messages: items,
    has_image: imageItems.length > 0,
    image_ids: imageItems.map(i => i.media_id),
    latest_timestamp: last.timestamp,
    batch_id: batchId,
    pending_message_ids: items.map(i => i.message_id),
    is_owner: whatsapp === ($env.OWNER_WHATSAPP || '')
  } });
}
return result;

const text = ($json.combined_text || '').trim();
const upper = text.toUpperCase();
let action = 'HELP';
let payload = {};
if (upper.startsWith('BUSCAR CLIENTE')) {
  action = 'BUSCAR_CLIENTE';
  payload.query = text.replace(/BUSCAR CLIENTE\s+/i, '').trim();
} else if (upper.startsWith('CONFIRMAR PAGO')) {
  action = 'CONFIRMAR_PAGO';
  payload.pago_id = text.replace(/CONFIRMAR PAGO\s+/i, '').trim();
} else if (upper.startsWith('RECHAZAR PAGO')) {
  action = 'RECHAZAR_PAGO';
  payload.pago_id = text.replace(/RECHAZAR PAGO\s+/i, '').trim();
} else if (upper.startsWith('ACTUALIZAR LINK')) {
  action = 'ACTUALIZAR_LINK';
  const match = text.match(/^ACTUALIZAR LINK\s+(\S+)\s+(.+)/i);
  payload = { cliente_id: match?.[1] || '', link_pago: match?.[2] || '' };
} else if (upper.startsWith('SUSPENDER')) {
  action = 'SUSPENDER';
  const match = text.match(/^SUSPENDER\s+(\S+)/i);
  payload = { cliente_id: match?.[1] || '' };
} else if (upper.startsWith('ACTIVAR')) {
  action = 'ACTIVAR';
  const match = text.match(/^ACTIVAR\s+(\S+)/i);
  payload = { cliente_id: match?.[1] || '' };
}
return [{ json: { action, payload, phone: $json.whatsapp, batch_id: $json.batch_id } }];

const command = $node['Admin: Parse comando'].json;
const clientes = $items('Admin: Leer clientes').map(i => i.json);
const pagos = $items('Admin: Leer pagos').map(i => i.json);
const now = new Date();
const todayIso = now.toISOString().slice(0, 10);
const normalizePhone = (value) => `+${String(value || '').replace(/\D/g, '')}`;
const findByQuery = (query) => {
  const clean = String(query || '').trim().toLowerCase();
  const digits = clean.replace(/\D/g, '');
  return clientes.filter(row => {
    const name = String(row.nombre || '').toLowerCase();
    const phone = normalizePhone(row.whatsapp || row.phone || '');
    return (digits && phone.includes(`+${digits}`)) || (clean && name.includes(clean));
  });
};
const findClienteById = (id) => clientes.find(row => String(row.cliente_id || '').toLowerCase() === String(id || '').toLowerCase());
const findPagoById = (id) => pagos.find(row => String(row.pago_id || '').toLowerCase() === String(id || '').toLowerCase());
const computeNextDue = (cliente) => {
  const diaPago = parseInt(cliente.dia_pago, 10);
  if (!Number.isNaN(diaPago)) {
    const year = now.getFullYear();
    const month = now.getMonth();
    const lastDay = new Date(year, month + 1, 0).getDate();
    const day = Math.min(Math.max(diaPago, 1), lastDay);
    let due = new Date(year, month, day);
    if (due < new Date(now.toDateString())) {
      const nextMonth = new Date(year, month + 1, 1);
      const lastDayNext = new Date(nextMonth.getFullYear(), nextMonth.getMonth() + 1, 0).getDate();
      const nextDay = Math.min(Math.max(diaPago, 1), lastDayNext);
      due = new Date(nextMonth.getFullYear(), nextMonth.getMonth(), nextDay);
    }
    return due.toISOString().slice(0, 10);
  }
  const base = cliente.proximo_vencimiento ? new Date(cliente.proximo_vencimiento) : new Date(now);
  if (Number.isNaN(base.getTime())) {
    const fallback = new Date(now);
    fallback.setDate(fallback.getDate() + 30);
    return fallback.toISOString().slice(0, 10);
  }
  base.setDate(base.getDate() + 30);
  return base.toISOString().slice(0, 10);
};
let messageToSend = 'Comando no reconocido. Usa: BUSCAR CLIENTE, CONFIRMAR PAGO, RECHAZAR PAGO, ACTUALIZAR LINK, SUSPENDER, ACTIVAR.';
let updateCliente = null;
let updatePago = null;
if (command.action === 'BUSCAR_CLIENTE') {
  const matches = findByQuery(command.payload.query || '');
  if (!matches.length) {
    messageToSend = 'No encontré clientes con ese dato.';
  } else {
    const lines = matches.slice(0, 3).map(c => {
      const nombre = c.nombre || 'Sin nombre';
      return `• ${nombre} | ${c.whatsapp || ''} | ${c.estado || ''} | Vence: ${c.proximo_vencimiento || ''} | Monto: ${c.monto_mensual || ''} | Link: ${c.link_pago || ''}`;
    });
    messageToSend = `Resultado:
${lines.join('\n')}`;
  }
} else if (command.action === 'CONFIRMAR_PAGO') {
  const pagoId = command.payload.pago_id || '';
  const pago = findPagoById(pagoId);
  if (!pago) {
    messageToSend = 'Pago no encontrado.';
  } else {
    updatePago = { pago_id: pagoId, validado_por: 'OWNER', nota: 'CONFIRMADO' };
    const cliente = findClienteById(pago.cliente_id);
    if (cliente) {
      const nextDue = computeNextDue(cliente);
      updateCliente = { cliente_id: cliente.cliente_id, fecha_ultimo_pago: todayIso, estado: 'ACTIVO', proximo_vencimiento: nextDue };
      messageToSend = `Pago confirmado ✅. Próximo vencimiento: ${nextDue}`;
    } else {
      messageToSend = 'Pago confirmado, pero cliente no encontrado.';
    }
  }
} else if (command.action === 'RECHAZAR_PAGO') {
  const pagoId = command.payload.pago_id || '';
  const pago = findPagoById(pagoId);
  if (!pago) {
    messageToSend = 'Pago no encontrado.';
  } else {
    updatePago = { pago_id: pagoId, validado_por: 'OWNER', nota: 'RECHAZADO' };
    messageToSend = 'Pago rechazado ✅';
  }
} else if (command.action === 'ACTUALIZAR_LINK') {
  const { cliente_id, link_pago } = command.payload;
  if (!cliente_id || !link_pago) {
    messageToSend = 'Formato: ACTUALIZAR LINK <cliente_id> <link>';
  } else {
    updateCliente = { cliente_id, link_pago };
    messageToSend = 'Link de pago actualizado ✅';
  }
} else if (command.action === 'SUSPENDER') {
  const { cliente_id } = command.payload;
  if (!cliente_id) {
    messageToSend = 'Formato: SUSPENDER <cliente_id>';
  } else {
    updateCliente = { cliente_id, estado: 'SUSPENDIDO' };
    messageToSend = 'Cliente suspendido ✅';
  }
} else if (command.action === 'ACTIVAR') {
  const { cliente_id } = command.payload;
  if (!cliente_id) {
    messageToSend = 'Formato: ACTIVAR <cliente_id>';
  } else {
    updateCliente = { cliente_id, estado: 'ACTIVO' };
    messageToSend = 'Cliente activado ✅';
  }
}
return [{ json: { messageToSend, updateCliente, updatePago, hasCliente: !!updateCliente, hasPago: !!updatePago, phone: command.phone, batch_id: command.batch_id } }];

const statusOk = !$json.error;
