let parseError = '';
try {
  const raw = $json.output?.[0]?.content?.[0]?.text || '';
  parsed = JSON.parse(raw);
} catch (e) {
  parseError = String(e.message || e);
  parsed = null;
}
const confidence = Number(parsed?.confidence_0_100 || 0);
const monto = Number(parsed?.monto || 0);
const mensual = Number(cliente?.monto_mensual || 0);
const montoVariable = String(cliente?.monto_variable || '').toUpperCase() === 'SI';
const diff = mensual ? Math.abs(monto - mensual) / mensual : 1;
const parseDate = (value) => {
  if (!value) return null;
  if (typeof value === 'number') {
    const utc = Math.round((value - 25569) * 86400 * 1000);
    return new Date(utc);
  }
  const parsedDate = new Date(value);
  return Number.isNaN(parsedDate.getTime()) ? null : parsedDate;
};
