else if (confidence < 80) reason = 'La imagen no es clara.';
else if (montoVariable || mensual <= 0) reason = 'Monto variable, necesito confirmación.';
else if (!montoOk) reason = 'El monto no coincide con tu plan.';
else if (!dateOk) reason = 'La fecha del pago no está dentro de los últimos 7 días.';
else if (duplicateRef) reason = 'La referencia ya existe, requiere revisión.';
