const statusOk = !$json.error;
return [{ json: {
  timestamp: new Date().toISOString(),
  cliente_id: '',
  whatsapp: $env.OWNER_WHATSAPP || '',
  tipo_mensaje: 'REPORTE',
  resumen: String($json.mensaje_final || '').slice(0, 120),
  message_key: `REPORTE_${new Date().toISOString().slice(0, 10)}`,
  status_envio: statusOk ? 'OK' : 'ERROR',
  error_envio: statusOk ? '' : String($json.error || ''),
  message_id: ''
} }];

const messageId = $node['Normalizar y validar'].json.message_id;
const inbox = $items('Dedupe: Leer inbox_buffer reciente').map(i => i.json);
const logs = $items('Dedupe: Leer mensajes_log reciente').map(i => i.json);
const inInbox = inbox.some(r => String(r.message_id || '').trim() === String(messageId || '').trim());
const inLogs = logs.some(r => String(r.message_id || '').trim() === String(messageId || '').trim());
return [{ json: { message_id: messageId, is_duplicate: inInbox || inLogs } }];

const binary = $binary.data;
if (!binary || !binary.data) {
  throw new Error('Media binaria no disponible');
}
const mime = binary.mimeType || 'image/jpeg';
const base64 = binary.data;
return [{ json: { image_data_url: `data:${mime};base64,${base64}`, mime } }];

const text = String($node['Buscar cliente'].json.combined_text || '').toUpperCase();
const match = ['STOP','BAJA','CANCELAR'].some(k => text.includes(k));
const cliente = $node['Buscar cliente'].json.cliente;
return [{ json: { optout: match, cliente, phone: $node['Buscar cliente'].json.phone, batch_id: $node['Buscar cliente'].json.batch_id, pending_message_ids: $node['Buscar cliente'].json.pending_message_ids } }];

const statusOk = !$json.error;
return [{ json: {
  timestamp: new Date().toISOString(),
  cliente_id: $node['Detectar BAJA/STOP'].json.cliente?.cliente_id || '',
  whatsapp: $node['Detectar BAJA/STOP'].json.phone || '',
  tipo_mensaje: 'BAJA',
  resumen: 'Baja confirmada',
  message_key: `BAJA_${$node['Detectar BAJA/STOP'].json.batch_id}` ,
  status_envio: statusOk ? 'OK' : 'ERROR',
  error_envio: statusOk ? '' : String($json.error || ''),
  message_id: $node['Detectar BAJA/STOP'].json.pending_message_ids?.[0] || ''
} }];

const messageIds = $node['Detectar BAJA/STOP'].json.pending_message_ids || [];
const batchId = $node['Detectar BAJA/STOP'].json.batch_id || '';
return messageIds.map(id => ({ json: { message_id: id, status: 'DONE', batch_id: batchId } }));
